CREATE DATABASE IF NOT EXISTS dharshanamart;
USE dharshanamart;
CREATE TABLE users (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('buyer','seller','admin') NOT NULL DEFAULT 'buyer', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE dresses (id INT PRIMARY KEY AUTO_INCREMENT, seller_id INT NOT NULL, name VARCHAR(150) NOT NULL, description TEXT NOT NULL, price DECIMAL(10,2) NOT NULL, category VARCHAR(80) NOT NULL, image_url VARCHAR(500), stock INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (seller_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE cart_items (user_id INT NOT NULL, dress_id INT NOT NULL, quantity INT NOT NULL DEFAULT 1, PRIMARY KEY (user_id,dress_id), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (dress_id) REFERENCES dresses(id) ON DELETE CASCADE);
CREATE TABLE wishlist_items (user_id INT NOT NULL, dress_id INT NOT NULL, PRIMARY KEY (user_id,dress_id), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (dress_id) REFERENCES dresses(id) ON DELETE CASCADE);
CREATE TABLE orders (id INT PRIMARY KEY AUTO_INCREMENT, buyer_id INT NOT NULL, total_amount DECIMAL(10,2) NOT NULL, status ENUM('pending','confirmed','shipped','delivered') NOT NULL DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (buyer_id) REFERENCES users(id));
CREATE TABLE order_items (id INT PRIMARY KEY AUTO_INCREMENT, order_id INT NOT NULL, dress_id INT NOT NULL, quantity INT NOT NULL, price DECIMAL(10,2) NOT NULL, FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY (dress_id) REFERENCES dresses(id));